package db.migration;

import java.sql.Connection;
import java.sql.Date;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

import org.flywaydb.core.api.migration.BaseJavaMigration;
import org.flywaydb.core.api.migration.Context;

import net.officefloor.hq.app.settings.SettingsRepository;

/** Terms count business days: each claim's due-by (and each kept in its history) is worked out again as the
 *  terms-th business day after its date, skipping Saturdays, Sundays and the holidays on its sheet now, with the
 *  terms it was fixed with. Those terms are the ones in force for it (the person's own, else their grade's on the
 *  date, else the sheet's on the date) when they give its stored calendar due-by (the date plus the terms, moved
 *  past the holidays); else the calendar days from its date to its due-by. */
public class V53__business_day_terms extends BaseJavaMigration {

    @Override
    public void migrate(Context context) throws Exception {
        Connection c = context.getConnection();
        Map<String, Set<String>> holidays = new HashMap<>();
        try (PreparedStatement ps = c.prepareStatement("SELECT sheet_id, holiday_date FROM holiday");
                ResultSet rs = ps.executeQuery()) {
            while (rs.next()) {
                holidays.computeIfAbsent(rs.getString(1), k -> new HashSet<>()).add(rs.getDate(2).toLocalDate().toString());
            }
        }
        Map<Long, Integer> termsOf = new HashMap<>();
        try (PreparedStatement claims = c.prepareStatement("SELECT id, sheet_id, person_id, claim_date, due_by FROM claim");
                ResultSet rs = claims.executeQuery();
                PreparedStatement update = c.prepareStatement("UPDATE claim SET due_by = ? WHERE id = ?")) {
            while (rs.next()) {
                long id = rs.getLong("id");
                String sheetId = rs.getString("sheet_id");
                LocalDate date = rs.getDate("claim_date").toLocalDate();
                LocalDate old = rs.getDate("due_by").toLocalDate();
                Set<String> sheetHolidays = holidays.getOrDefault(sheetId, Set.of());
                Integer inForce = termsInForce(c, sheetId, rs.getLong("person_id"), date);
                int terms = inForce != null && inForce >= 0 && pastHolidays(sheetHolidays, date.plusDays(inForce)).equals(old)
                        ? inForce : (int) Math.max(0, ChronoUnit.DAYS.between(date, old));
                termsOf.put(id, terms);
                update.setDate(1, Date.valueOf(SettingsRepository.businessDaysAfter(sheetHolidays, date, terms)));
                update.setLong(2, id);
                update.executeUpdate();
            }
        }
        try (PreparedStatement history = c.prepareStatement("SELECT id, sheet_id, claim_id, claim_date, due_by FROM claim_history");
                ResultSet rs = history.executeQuery();
                PreparedStatement update = c.prepareStatement("UPDATE claim_history SET due_by = ? WHERE id = ?")) {
            while (rs.next()) {
                LocalDate date = rs.getDate("claim_date").toLocalDate();
                Integer terms = termsOf.get(rs.getLong("claim_id"));
                if (terms == null) terms = (int) Math.max(0, ChronoUnit.DAYS.between(date, rs.getDate("due_by").toLocalDate()));
                update.setDate(1, Date.valueOf(SettingsRepository.businessDaysAfter(
                        holidays.getOrDefault(rs.getString("sheet_id"), Set.of()), date, terms)));
                update.setLong(2, rs.getLong("id"));
                update.executeUpdate();
            }
        }
    }

    private static LocalDate pastHolidays(Set<String> holidays, LocalDate date) {
        while (holidays.contains(date.toString())) date = date.plusDays(1);
        return date;
    }

    /** The person's own terms, else their grade's in force on the date, else the sheet's in force on it (14 before any). */
    private static Integer termsInForce(Connection c, String sheetId, long personId, LocalDate date) throws Exception {
        try (PreparedStatement ps = c.prepareStatement("SELECT terms FROM person WHERE id = ?")) {
            ps.setLong(1, personId);
            try (ResultSet rs = ps.executeQuery()) {
                if (rs.next() && rs.getObject(1) != null) return rs.getInt(1);
            }
        }
        String grade = null;
        try (PreparedStatement ps = c.prepareStatement("SELECT grade FROM person_grade WHERE person_id = ?"
                + " AND (from_date IS NULL OR from_date <= ?) ORDER BY from_date DESC NULLS LAST LIMIT 1")) {
            ps.setLong(1, personId);
            ps.setDate(2, Date.valueOf(date));
            try (ResultSet rs = ps.executeQuery()) {
                if (rs.next()) grade = rs.getString(1);
            }
        }
        if (grade != null) {
            String own = setting(c, sheetId, "terms-" + grade, date);
            if (own != null) return Integer.valueOf(own);
        }
        String terms = setting(c, sheetId, "terms", date);
        return terms == null ? 14 : Integer.valueOf(terms);
    }

    private static String setting(Connection c, String sheetId, String key, LocalDate date) throws Exception {
        try (PreparedStatement ps = c.prepareStatement("SELECT setting FROM setting_value WHERE sheet_id = ? AND setting_key = ?"
                + " AND from_date <= ? ORDER BY from_date DESC LIMIT 1")) {
            ps.setString(1, sheetId);
            ps.setString(2, key);
            ps.setDate(3, Date.valueOf(date));
            try (ResultSet rs = ps.executeQuery()) {
                return rs.next() ? rs.getString(1) : null;
            }
        }
    }
}
package net.officefloor.hq.app.sheet;

import java.sql.Date;
import java.time.LocalDate;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

@Repository
public class SheetRepository {

    private final JdbcTemplate jdbc;

    public SheetRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet with this id, made empty (its today the real date) when the id was never used. */
    public Sheet loadOrCreate(String id, String user) {
        Integer known = jdbc.queryForObject("SELECT COUNT(*) FROM sheet WHERE id = ?", Integer.class, id);
        if (known == null || known == 0) {
            try {
                jdbc.update("INSERT INTO sheet (id, created_by, today) VALUES (?, ?, ?)", id, user,
                        Date.valueOf(LocalDate.now()));
            } catch (DuplicateKeyException made) {
                // another user loaded the same new id at the same moment: it is made either way
            }
        }
        return new Sheet(id, today(id).toString(), archived(id));
    }

    /** The sheet's today: the date every date decision and default in the sheet uses. */
    public LocalDate today(String id) {
        Date today = jdbc.queryForObject("SELECT today FROM sheet WHERE id = ?", Date.class, id);
        return today.toLocalDate();
    }

    /** The default date of a new claim: the sheet's entry date while one is set, else its today. */
    public LocalDate entryDate(String id) {
        Date date = jdbc.queryForObject("SELECT COALESCE(entry_date, today) FROM sheet WHERE id = ?", Date.class, id);
        return date.toLocalDate();
    }

    /** Whether a steward has archived the sheet. */
    public boolean archived(String id) {
        Boolean archived = jdbc.queryForObject("SELECT archived FROM sheet WHERE id = ?", Boolean.class, id);
        return Boolean.TRUE.equals(archived);
    }

    /** Archive the sheet; false when there is no such sheet. */
    public boolean archive(String id) {
        return jdbc.update("UPDATE sheet SET archived = TRUE WHERE id = ?", id) > 0;
    }

    /** Set the sheet's today; false when there is no such sheet. */
    public boolean setToday(String id, LocalDate today) {
        return jdbc.update("UPDATE sheet SET today = ? WHERE id = ?", Date.valueOf(today), id) > 0;
    }
}
package net.officefloor.hq.app.sheet;

import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.CurrentUser;
import net.officefloor.plugin.variable.Out;
import net.officefloor.server.http.ServerHttpConnection;
import org.springframework.web.bind.annotation.PathVariable;

public class LoadSheet {
    public void load(@PathVariable("sheetId") String sheetId, ServerHttpConnection connection,
            SheetRepository repository, Out<Sheet> sheet) throws BadRequestException {
        String by = CurrentUser.require(connection);
        String id = sheetId == null ? "" : sheetId.trim();
        if (id.isEmpty()) {
            throw new BadRequestException("sheet id is required");
        }
        sheet.set(repository.loadOrCreate(id, by));
    }
}
package net.officefloor.hq.app.sheet;

/** A sheet: its id, its own today (ISO yyyy-MM-dd), which stands in for the real date, and whether a steward
 *  has archived it (nothing on it can then be changed). */
public record Sheet(String id, String today, boolean archived) {
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.CurrentUser;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.settings.SettingsRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.server.http.ServerHttpConnection;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

/** A steward transfers a person to another sheet by id: they arrive there with every grade they were given (and
 *  its from-date), their terms, contact and aliases, and their claims (see {@link ClaimRepository#transferAll}), with
 *  no statements; they leave this sheet entirely (patron links, pool memberships, holds and watches dropped).
 *  A sheet id never used is made empty first, as loading it would. Refused for anyone but a steward, for a retired
 *  person, for this sheet's own id, for an archived sheet, and when their name, an alias or their contact is already
 *  on the other sheet. Each sheet writes its PERSON_TRANSFERRED line, then its rollup lines. */
public class TransferPerson {
    public void transfer(@PathVariable("sheetId") String sheetId, @PathVariable("personId") String personId,
            @RequestBody TransferRequest request, ServerHttpConnection connection, PersonRepository people,
            AliasRepository aliases, ClaimRepository claims, SettingsRepository settings, SheetRepository sheets, Audit audit,
            Rollup rollup,
            Out<Person> person) throws BadRequestException {
        String by = CurrentUser.require(connection);
        String id = sheetId == null ? "" : sheetId.trim();
        long pid;
        try {
            pid = Long.parseLong(personId == null ? "" : personId.trim());
        } catch (NumberFormatException e) {
            throw new BadRequestException("no such person");
        }
        Person from = people.find(id, pid);
        if (from == null) {
            throw new BadRequestException("no such person");
        }
        if (!settings.role(id, by).equals(SettingsRepository.STEWARD)) {
            throw new BadRequestException("only a steward can transfer people");
        }
        if (from.retired()) {
            throw new BadRequestException(from.name() + " is retired");
        }
        String to = request == null || request.toSheetId() == null ? "" : request.toSheetId().trim();
        if (to.isEmpty()) {
            throw new BadRequestException("enter the sheet to transfer to");
        }
        if (to.equals(id)) {
            throw new BadRequestException("a person cannot be transferred to their own sheet");
        }
        if (settings.archived(to)) {
            throw new BadRequestException("sheet " + to + " is archived");
        }
        if (people.nameTaken(to, from.name(), pid)) {
            throw new BadRequestException(from.name() + " is already on sheet " + to);
        }
        for (Alias alias : aliases.list(id)) {
            if (alias.personId() == pid && people.nameTaken(to, alias.alias(), pid)) {
                throw new BadRequestException(alias.alias() + " is already on sheet " + to);
            }
        }
        if (from.contact() != null && people.contactTaken(to, from.contact(), 0)) {
            throw new BadRequestException(from.contact() + " is already on sheet " + to);
        }

        if (!people.sheetExists(to)) {
            sheets.loadOrCreate(to, by);
        }
        Rollup.Snapshot beforeHere = rollup.take(id);
        Rollup.Snapshot beforeThere = rollup.take(to);
        long arrived = people.transferIn(id, pid, to);
        claims.transferAll(id, pid, to, arrived);
        people.remove(id, pid);
        audit.record("PERSON_TRANSFERRED sheet=" + id + " by=" + by + " name=" + from.name() + " to=" + to);
        rollup.record(id, by, beforeHere);
        audit.record("PERSON_TRANSFERRED sheet=" + to + " by=" + by + " name=" + from.name() + " from=" + id);
        rollup.record(to, by, beforeThere);
        person.set(people.find(to, arrived));
    }
}
# A steward transfers a person to another sheet by id (not this one; not a retired person; no name, alias or
# contact of theirs already there): their grades, terms, contact, aliases and claims go with them, and they
# leave this sheet.
guard:
  class: net.officefloor.hq.app.settings.RefuseViewer
  next: transfer
transfer:
  class: net.officefloor.hq.app.person.TransferPerson
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.person.RespondWithPerson
# Load a sheet by id: made (empty) the first time the id is used, re-read from the store after.
load:
  class: net.officefloor.hq.app.sheet.LoadSheet
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.sheet.RespondWithSheet

