487-  const done = async () => (await shown(page.getByTestId('sheet-cloned-to'))) === toSheet;
488-  const already = await done();
489-  await page.getByTestId('sheet-clone-to').fill(toSheet);
490-  await page.getByTestId('sheet-clone').click();
