494-/** The ids of the person rows in screen order. */
495-export async function personOrder(page: Page): Promise<string[]> {
496-  return ids(rows(page), 'person-row-');
497-}
498-
499-/** Move the person up or down the list: true once their place in the list changed. */
500-export async function movePerson(page: Page, personId: string, direction: string): Promise<boolean> {
501-  const was = (await personOrder(page)).indexOf(personId);
502-  const r = row(page, personId);
503-  await r.getByTestId(`person-move-${direction}`).click();
504-  return until(page, async () => (await personOrder(page)).indexOf(personId) !== was,
505-    r.getByTestId('person-error'), 'move person');
506-}
