508-export async function sortBy(page: Page, key: string): Promise<void> {
509-  await page.getByTestId('sort-by').selectOption(key);
510-  await page.waitForTimeout(200);
511-}
--
691:export async function claimAt(page: Page, personId: string, idx: number): Promise<string> {
692-  const all = claimRows(row(page, personId));
693-  const n = await all.count();
694-  const r = all.nth(n - 1 - idx);
695-  await expect(r).toBeVisible({ timeout: WAIT });
696-  return idOf(await r.getAttribute('data-testid'), 'claim-row-');
697-}
