699-type ClaimFields = { amount?: string; date?: string; note?: string; corrects?: string; ref?: string; tags?: string };
700-
701-/** Fill the claim form. `clear` (an add) also empties every field the test does not give (a
702- *  blank date takes the default), so nothing typed for a refused add carries into this one; an
703- *  edit leaves the fields it is not given as the editor filled them. */
704-async function fillClaimForm(r: Locator, f: ClaimFields, clear = false) {
705-  for (const key of ['amount', 'date', 'note', 'corrects', 'ref', 'tags'] as const) {
706-    const v = f[key];
707-    if (v !== undefined) await r.getByTestId(`claim-form-${key}`).fill(v);
708-    else if (clear) await setField(r, `claim-form-${key}`, undefined);
709-  }
710-}
711-
712-/** Add a claim from the person's row. The new claim's id, or null when refused. */
713-export async function addClaim(page: Page, personId: string, f: ClaimFields & { amount: string }): Promise<string | null> {
714-  const r = row(page, personId);
715-  const before = await ids(claimRows(r), 'claim-row-');
716-  await fillClaimForm(r, f, true);

